"""Veridex updater. Put this file in the veridex folder (next to README.md) and run:  python update_7.py"""
import base64, os
HERE = os.path.dirname(os.path.abspath(__file__))
FILES = {'db.py': '', 'zeus/hunter.py': '', 'api/main.py': '', 'requirements.txt': 'ZmFzdGFwaQpnVFRTCmh0dHB4CmltYWdlaW8tZmZtcGVnCmtoYXlhCnBhbmRhcwpweXRob24tdGVsZWdyYW0tYm90CnJhcGlkZnV6egpzdHJlYW1saXQKdXZpY29ybgo='}
for rel, b in FILES.items():
    p = os.path.join(HERE, *rel.split("/"))
    os.makedirs(os.path.dirname(p), exist_ok=True)
    open(p, "wb").write(base64.b64decode(b))
    print("updated", rel)
print("Done. Now run: pip install -r requirements.txt   then restart the bot.")
